use crate::{App, Page, theme};
use eframe::egui::{self, Color32, RichText, TextureHandle};

const ACCENT:Color32=Color32::from_rgb(184,74,36);
fn eyebrow(ui:&mut egui::Ui,text:&str){let color=if ui.visuals().dark_mode {Color32::from_rgb(239,154,115)}else{ACCENT};ui.label(RichText::new(text).size(12.0).strong().color(color));}
fn card(ui:&egui::Ui, muted:bool)->egui::Frame {egui::Frame::none().fill(if muted {ui.visuals().widgets.inactive.bg_fill}else{ui.visuals().window_fill}).stroke(egui::Stroke::new(1.0_f32,ui.visuals().widgets.noninteractive.bg_stroke.color)).rounding(18.0).inner_margin(egui::Margin::same(24.0))}
fn primary(text:&str)->egui::Button<'_>{egui::Button::new(RichText::new(text).color(Color32::WHITE).strong()).fill(ACCENT).rounding(10.0)}
pub fn lockup(ui:&mut egui::Ui,descriptor:&str){ui.horizontal(|ui|{theme::brand(ui);ui.vertical(|ui|{ui.label(RichText::new("goodstock").size(21.0).strong());ui.label(RichText::new(descriptor.to_uppercase()).size(9.0).strong());});});}
pub fn textures(ctx:&egui::Context)->Vec<Option<TextureHandle>> {
    let images:[Option<&[u8]>;12]=[None,None,Some(include_bytes!("../assets/images/m12-washer.webp")),Some(include_bytes!("../assets/images/torx-screwdriver-set.webp")),Some(include_bytes!("../assets/images/phillips-screwdriver.webp")),Some(include_bytes!("../assets/images/tape-measure.webp")),Some(include_bytes!("../assets/images/needle-nose-pliers.webp")),Some(include_bytes!("../assets/images/combination-wrenches.webp")),Some(include_bytes!("../assets/images/polyimide-tape.webp")),Some(include_bytes!("../assets/images/glass-fuse.webp")),Some(include_bytes!("../assets/images/omron-relay.webp")),Some(include_bytes!("../assets/images/miniature-circuit-breaker.webp"))];
    images.iter().enumerate().map(|(i,bytes)|bytes.and_then(|bytes|image::load_from_memory(bytes).ok()).map(|image|{let image=image.to_rgba8();let size=[image.width() as usize,image.height() as usize];ctx.load_texture(format!("product-{i}"),egui::ColorImage::from_rgba_unmultiplied(size,image.as_raw()),egui::TextureOptions::LINEAR)})).collect()
}
fn picture(ui:&mut egui::Ui,tex:Option<&TextureHandle>,height:f32){let width=ui.available_width().max(1.0);let (rect,_)=ui.allocate_exact_size(egui::vec2(width,height),egui::Sense::hover());ui.painter().rect_filled(rect,10.0,if ui.visuals().dark_mode {Color32::from_rgb(35,47,42)}else{Color32::from_rgb(235,236,229)});if let Some(tex)=tex{let size=tex.size_vec2();let scale=(width/size.x).min(height/size.y);let fitted=egui::Rect::from_center_size(rect.center(),size*scale);ui.painter().image(tex.id(),fitted,egui::Rect::from_min_max(egui::pos2(0.0,0.0),egui::pos2(1.0,1.0)),Color32::WHITE);}else{ui.painter().text(rect.center(),egui::Align2::CENTER_CENTER,"GOODSTOCK",egui::FontId::proportional(15.0),ui.visuals().weak_text_color());}}
fn product_texture<'a>(app:&'a App,sku:&str)->Option<&'a TextureHandle>{let i=sku.strip_prefix("GS-")?.parse::<usize>().ok()?.checked_sub(1)?;app.textures.as_ref()?.get(i)?.as_ref()}

pub fn entry(app:&mut App,ui:&mut egui::Ui){egui::ScrollArea::vertical().show(ui,|ui|{ui.add_space(28.0);ui.set_max_width(1200.0);ui.horizontal(|ui|{lockup(ui,"hardware");ui.with_layout(egui::Layout::right_to_left(egui::Align::Center),|ui|{if ui.button(if app.dark{"Light"}else{"Dark"}).clicked(){app.dark=!app.dark;theme::apply(ui.ctx(),app.dark)}});});ui.add_space(36.0);eyebrow(ui,"GOODSTOCK HARDWARE PLATFORM");ui.label(RichText::new("Choose where you want to work.").size(42.0).strong());ui.label(RichText::new("Shop the Goodstock Hardware storefront or switch into the staff operations workspace for inventory, counter sales, and demand forecasting.").size(17.0));ui.add_space(24.0);
let cols=if ui.available_width()<650.0 {1}else{2};let items=[false,true];for chunk in items.chunks(cols){ui.columns(cols,|columns|{for (col,business) in chunk.iter().enumerate(){let u=&mut columns[col];card(u,*business).show(u,|ui|{ui.set_min_height(260.0);ui.label(RichText::new(if *business{"▦"}else{"▣"}).size(26.0));eyebrow(ui,if *business{"STAFF WORKSPACE"}else{"ONLINE STOREFRONT"});ui.label(RichText::new(if *business{"Business operations"}else{"Shop Goodstock Hardware"}).size(25.0).strong());ui.label(if *business{"Manage inventory levels, record point-of-sale counter receipts, monitor online orders, and run demand analytics."}else{"Browse fasteners, hand tools, and electrical parts, manage your cart, and place orders for delivery or counter pickup."});ui.add_space(10.0);ui.label(if *business{"• Inventory, POS & demand forecasting"}else{"• Complete hardware catalog & local inventory"});ui.add_space(15.0);ui.horizontal_wrapped(|ui|{if ui.add(primary(if *business{"Open workspace →"}else{"Enter storefront →"})).clicked(){if *business {if app.signed_in=="admin@goodstock.ph" {app.page=Page::Overview}else{app.workspace_requested=true;app.login=true;app.status="Sign in as administrator to open the workspace".into();}} else {app.page=Page::Home}}if ui.button(if *business{"Account settings"}else{"Browse catalog"}).clicked(){if *business{app.login=true}else{app.category="All".into();app.page=Page::Shop}}});});}});ui.add_space(10.0);}});}

pub fn home(app:&mut App,ui:&mut egui::Ui){egui::ScrollArea::vertical().id_salt("store-home").show(ui,|ui|{ui.add_space(20.0);card(ui,false).show(ui,|ui|{let cols=if ui.available_width()<680.0{1}else{2};ui.columns(cols,|c|{let u=&mut c[0];eyebrow(u,"DEPENDABLE WORKSHOP SUPPLY");u.add_space(12.0);u.label(RichText::new("Build the fix.\nMake it last.").size(42.0).strong());u.label(RichText::new("Thoughtfully stocked fasteners, hand tools, and electrical essentials—ready for contractor jobs, studio builds, and repairs you want done once.").size(16.0));u.add_space(14.0);u.horizontal_wrapped(|ui|{if ui.add(primary("Shop all hardware →")).clicked(){app.category="All".into();app.page=Page::Shop}if ui.button("Orders & account").clicked(){app.page=Page::History}});u.add_space(20.0);u.separator();u.horizontal_wrapped(|ui|{for title in ["✓ Practical picks","◈ Clear details","▣ Counter pickup"]{ui.strong(title);}});
if cols>1 {let u=&mut c[1];card(u,true).show(u,|ui|{picture(ui,app.textures.as_ref().and_then(|t|t.get(7)).and_then(|t|t.as_ref()),190.0);ui.horizontal_wrapped(|ui|{ui.strong(format!("{} catalog SKUs",app.state.products.len()));ui.strong(format!("{} in stock",app.state.products.iter().filter(|p|p.stock>0).count()));});ui.label("Featured bench essential");ui.strong("Clear specs before it goes in the bag.");});}});});ui.add_space(32.0);eyebrow(ui,"FIND YOUR AISLE");ui.label(RichText::new("Start with what the job calls for.").size(27.0).strong());ui.add_space(10.0);let categories=[("Fasteners","Screws, bolts, washers, and structural hardware built to hold repairs together."),("Tools","Drivers, wrenches, pliers, and measuring gear for repeat bench work."),("Power & Electrical","Breakers, relays, regulators, fuses, and bench components.")];let cols=if ui.available_width()<700.0{1}else{3};for group in categories.chunks(cols){ui.columns(cols,|c|{for (i,(name,copy)) in group.iter().enumerate(){let u=&mut c[i];card(u,false).show(u,|ui|{ui.set_min_height(140.0);ui.label(RichText::new(*name).size(20.0).strong());ui.label(*copy);if ui.button("Explore aisle →").clicked(){app.category=(*name).into();app.page=Page::Shop}});}});ui.add_space(10.0);}ui.add_space(16.0);eyebrow(ui,"READY TO SHIP");ui.label(RichText::new("Reliable parts for the bench.").size(27.0).strong());if ui.button("Browse full catalog →").clicked(){app.category="All".into();app.page=Page::Shop}ui.small("Product photos are illustrative; see image credits in the application documentation.");});}
pub fn catalog(app:&mut App,ui:&mut egui::Ui){
    egui::ScrollArea::vertical().id_salt("shop-scroll").show(ui,|ui|{
        ui.add_space(14.0);eyebrow(ui,"THE SHOP");ui.label(RichText::new("Parts for projects that need to get done.").size(34.0).strong());
        ui.label("Browse fasteners, tools, and electrical components, compare specifications, and build a cart when you're ready.");
        ui.add_space(12.0);ui.horizontal_wrapped(|ui|{ui.strong(format!("{} catalog SKUs",app.state.products.len()));ui.separator();ui.strong(format!("{} in stock",app.state.products.iter().filter(|p|p.stock>0).count()));});ui.add_space(20.0);
        let wide=ui.available_width()>720.0;
        // Allocate a fixed filter column, leaving the remaining width to the catalog.
        if wide {ui.horizontal_top(|ui|{ui.allocate_ui_with_layout(egui::vec2(210.0,ui.available_height()),egui::Layout::top_down(egui::Align::Min),|ui|filters(app,ui));ui.separator();ui.vertical(|ui|products(app,ui));});} else {filters(app,ui);ui.separator();products(app,ui);}
    });
}
fn filters(app:&mut App,ui:&mut egui::Ui){card(ui,false).show(ui,|ui|{ui.set_min_width(170.0);ui.label(RichText::new("Filters").size(20.0).strong());ui.label("Find the right hardware");ui.separator();ui.strong("AISLES");for cat in ["All","Fasteners","Tools","Power & Electrical"] {let label=if cat=="All"{"All hardware"}else{cat};if ui.selectable_label(app.category==cat,label).clicked(){app.category=cat.into()}}ui.separator();ui.checkbox(&mut app.in_stock,"In stock only");if ui.button("Clear filters").clicked(){app.search.clear();app.category="All".into();app.in_stock=false;app.sort=0;}});}
fn products(app:&mut App,ui:&mut egui::Ui){
    ui.horizontal_wrapped(|ui|{ui.add(egui::TextEdit::singleline(&mut app.search).hint_text("Search hardware or SKU").desired_width(220.0));egui::ComboBox::from_id_salt("sort").selected_text(["Featured","Price: low to high","Price: high to low","Name"][app.sort]).show_ui(ui,|ui|{for (i,s) in ["Featured","Price: low to high","Price: high to low","Name"].iter().enumerate(){ui.selectable_value(&mut app.sort,i,*s);}});});
    let q=app.search.to_lowercase();let mut ids:Vec<usize>=app.state.products.iter().enumerate().filter(|(_,p)|(app.category=="All"||p.category==app.category)&&(!app.in_stock||p.stock>0)&&(p.name.to_lowercase().contains(&q)||p.sku.to_lowercase().contains(&q)||p.description.to_lowercase().contains(&q))).map(|(i,_)|i).collect();
    match app.sort {1=>ids.sort_by(|a,b|app.state.products[*a].price.total_cmp(&app.state.products[*b].price)),2=>ids.sort_by(|a,b|app.state.products[*b].price.total_cmp(&app.state.products[*a].price)),3=>ids.sort_by(|a,b|app.state.products[*a].name.cmp(&app.state.products[*b].name)),_=>{}}
    ui.label(format!("{} products",ids.len()));let count=if ui.available_width()>670.0 {3}else if ui.available_width()>380.0 {2}else{1};
    for group in ids.chunks(count){ui.columns(count,|cols|{for (col,&i) in group.iter().enumerate(){let p=app.state.products[i].clone();let u=&mut cols[col];card(u,false).show(u,|ui|{picture(ui,product_texture(app,&p.sku),145.0);eyebrow(ui,&p.category.to_uppercase());ui.label(RichText::new(&p.name).size(15.0).strong());ui.label(format!("{} · {}",p.sku,if p.stock>0 {"In stock"}else{"Out of stock"}));ui.label(RichText::new(format!("₱{:.2}",p.price)).size(17.0).strong());ui.horizontal_wrapped(|ui|{if ui.button("Details").clicked(){app.details=Some(i)}if ui.add_enabled(p.stock>0,primary("Add to cart")).clicked(){App::add(&mut app.cart,&p)}});});}});ui.add_space(10.0);}ui.small("Images are illustrative, not verified photographs of the listed products.");
}
pub fn header(app:&mut App,ctx:&egui::Context){
    let business=matches!(app.page,Page::Overview|Page::Inventory|Page::Pos|Page::Forecast);
    if app.page==Page::Entry{return}
    if business {
        egui::SidePanel::left("business-nav").exact_width(225.0).frame(egui::Frame::none().fill(ctx.style().visuals.window_fill).inner_margin(egui::Margin::same(18.0))).show(ctx,|ui|{lockup(ui,"workspace");ui.add_space(28.0);eyebrow(ui,"WORKSPACE");for (p,label) in [(Page::Overview,"▦   Overview"),(Page::Inventory,"▣   Inventory"),(Page::Pos,"▤   Counter sales"),(Page::Forecast,"◷   Knowledge analysis")] {if ui.add_sized([185.0,40.0],egui::Button::new(label).selected(app.page==p)).clicked(){app.page=p;}}ui.add_space(20.0);if ui.button("Settings").clicked(){app.settings=true;}if ui.button("← Back to storefront").clicked(){app.page=Page::Home}if ui.button("Change password").clicked(){app.change_password=true;}if ui.button("Sign out").clicked(){app.signed_in.clear();app.page=Page::Entry;}});
        egui::TopBottomPanel::top("business-header").frame(egui::Frame::none().fill(ctx.style().visuals.window_fill).inner_margin(egui::Margin::same(15.0))).show(ctx,|ui|{ui.horizontal(|ui|{ui.label("Business workspace  /  ");ui.strong(match app.page {Page::Overview=>"Overview",Page::Inventory=>"Inventory",Page::Pos=>"Counter sales",_=>"Knowledge analysis"});ui.with_layout(egui::Layout::right_to_left(egui::Align::Center),|ui|{if ui.button(if app.dark{"Light"}else{"Dark"}).clicked(){app.dark=!app.dark;theme::apply(ctx,app.dark)}});});});return
    }
    egui::TopBottomPanel::top("store-header").frame(egui::Frame::none().fill(ctx.style().visuals.window_fill)).show(ctx,|ui|{
        egui::Frame::none().fill(Color32::from_rgb(24,37,32)).inner_margin(egui::Margin::symmetric(20.0,7.0)).show(ui,|ui|{ui.horizontal_wrapped(|ui|{ui.label(RichText::new("Good tools. Clear choices. Back to the work.").color(Color32::from_rgb(232,239,235)).size(12.0));});});
        ui.add_space(5.0);ui.horizontal_wrapped(|ui|{if ui.button("⌂").on_hover_text("Choose workspace").clicked(){app.page=Page::Entry}lockup(ui,"hardware");ui.add(egui::TextEdit::singleline(&mut app.search).hint_text("Search fasteners, tools, electrical…").desired_width(270.0));if ui.button("Search").clicked(){app.page=Page::Shop;}if ui.button(if app.dark{"Light"}else{"Dark"}).clicked(){app.dark=!app.dark;theme::apply(ctx,app.dark)}if ui.button(if app.signed_in.is_empty(){"Account"}else{"Orders"}).clicked(){if app.signed_in.is_empty(){app.login=true}else{app.page=Page::History}}if ui.button(format!("Cart ({})",app.cart.iter().map(|(_,q)|q).sum::<i32>())).clicked(){app.drawer=!app.drawer}});ui.separator();
        ui.horizontal_wrapped(|ui|{for (cat,label) in [("All","Shop all"),("Fasteners","Fasteners"),("Tools","Tools"),("Power & Electrical","Power & electrical")] {if ui.selectable_label(app.page==Page::Shop&&app.category==cat,label).clicked(){app.category=cat.into();app.page=Page::Shop}}if ui.button("Business workspace ↗").clicked(){if app.signed_in=="admin@goodstock.ph" {app.page=Page::Overview}else{app.workspace_requested=true;app.login=true;app.status="Sign in as administrator to open the workspace".into();}}});
    });
}
